USE [AppDB];

-- Grant SELECT on a specific table
GRANT SELECT ON OBJECT::[dbo].[Customers] TO [ReportReaders];

-- Grant SELECT on an entire schema
GRANT SELECT ON SCHEMA::[Sales] TO [ReportReaders];

-- Grant EXECUTE on a stored procedure
GRANT EXECUTE ON OBJECT::[dbo].[sp_GetCustomerReport] TO [ReportReaders];

-- Grant with ability to delegate
GRANT SELECT ON OBJECT::[dbo].[Customers] TO [jane.doe] WITH GRANT OPTION;

USE [AppDB];

-- Revoke SELECT on a table
REVOKE SELECT ON OBJECT::[dbo].[Customers] FROM [ReportReaders];

-- Revoke the grant option only, keeping the base grant
REVOKE GRANT OPTION FOR SELECT ON OBJECT::[dbo].[Customers] FROM [jane.doe];

-- Remove all permissions granted through a role
REVOKE SELECT ON SCHEMA::[Sales] FROM [ReportReaders];

USE [AppDB];

-- Deny ALTER on a critical table
DENY ALTER ON OBJECT::[dbo].[Financials] TO [AppWriters];

-- Deny VIEW DEFINITION on sensitive schemas
DENY VIEW DEFINITION ON SCHEMA::[HR] TO [ReportReaders];

-- Deny INSERT on an audit table to prevent tampering
DENY INSERT, UPDATE, DELETE ON OBJECT::[dbo].[AuditLog] TO [AppWriters];

